<div class="chat-settings-panel" hidden><div class="chat-settings-head"><strong>Chat settings</strong><button type="button" data-chat-settings-close>×</button></div><div class="chat-settings-contact"><span class="chat-settings-avatar">${avatar}</span><div><strong>${safe(title)}</strong><small>TM ID ${safe(other.tm_number||"")}</small></div></div><button type="button" class="chat-settings-option" data-chat-copy-id>Copy TM ID</button><button type="button" class="chat-settings-option" data-chat-mute>${muted?"Unmute this chat":"Mute this chat"}</button><button type="button" class="chat-settings-option" data-chat-refresh>Refresh messages</button><button type="button" class="chat-settings-option" data-chat-delete>Delete conversation for me</button><button type="button" class="chat-settings-option chat-danger-option" data-chat-block>Block this person</button><button type="button" class="chat-settings-option" data-chat-back>Back to chats</button><p class="chat-settings-note">Mute is saved on this device.</p></div>
